def is_nested(string):
    # Per team note: a nested pair counts only if the whole string is balanced.
    # First validate that the entire string is a balanced bracket sequence.
    depth = 0
    for ch in string:
        if ch == '[':
            depth += 1
        elif ch == ']':
            depth -= 1
            if depth < 0:
                return False
    if depth != 0:
        return False

    # Now the string is balanced. Check whether any bracket is nested,
    # i.e., depth reaches 2 at some point.
    depth = 0
    for ch in string:
        if ch == '[':
            depth += 1
            if depth >= 2:
                return True
        elif ch == ']':
            depth -= 1
    return False
